-- 099_phase1a_entity_correction.sql
-- Phase 1a: Canonical platform entity metadata backfill across control, document, master, shared schemas.
--
-- Scope rule:
--   tenant_id IS NULL = platform standard metadata, safe for seed repair.
--   tenant_id IS NOT NULL = tenant override/customisation, never touched here.
--
-- SAFE UPDATE only — patches slug, entity_short, entity_class, governance_level,
-- security_tier, mutability, mapping_mode, label_singular, label_plural.
-- Does NOT rename entity_code or name on existing rows (Phase 1b handles that).
-- New platform rows are inserted with table-name-only name/entity_code/slug.
--
-- Lookup value mappings applied:
--   governance_level : audit_only → lite  |  light → standard
--   security_tier    : sensitive  → tenant_critical  |  business → operational
--   entity_class     : SHARED → REFERENCE
--
-- Idempotent: ON CONFLICT (table_schema, table_name) DO UPDATE

DO $$
DECLARE
    v_su  uuid := '00000000-0000-0000-0000-000000000000';
    v_fnd uuid;
    v_acc uuid;
    v_count integer;
BEGIN
    SELECT id INTO v_fnd FROM shared.module WHERE code = 'FND';
    SELECT id INTO v_acc FROM shared.module WHERE code = 'ACC';

    -- ── Slug backfill for rows still missing one ───────────────────────────────
    UPDATE control.entity
       SET slug       = replace(lower(table_name), '_', '-'),
           updated_at = now(),
           updated_by = v_su
     WHERE tenant_id IS NULL
       AND slug IS NULL
       AND table_schema IN ('control', 'document', 'master', 'shared');

    -- ── Canonical metadata upsert ──────────────────────────────────────────────
    -- Columns: tbl_schema, tbl_name, entity_short, entity_class,
    --          gov_level, sec_tier, mutab, label_s, label_p, backing
