        ('shared','plan_permission_access',                'PPA',    'REFERENCE','lite','config',         'locked',   'Plan Permission Access',               'Plan Permission Access',               'table'),
        ('shared','role',                                  'ROLE',   'REFERENCE','lite','config',         'locked',   'Role',                                 'Roles',                                'table'),
        ('shared','permission',                            'PESH',   'REFERENCE','lite','config',         'locked',   'Permission',                           'Permissions',                          'table'),
        ('shared','commodity_crosswalk',                   'CCSH',   'REFERENCE','lite','config',         'locked',   'Commodity Crosswalk',                  'Commodity Crosswalks',                 'table'),
        ('shared','persona_permission',                    'PPS',    'REFERENCE','lite','config',         'locked',   'Persona Permission',                   'Persona Permissions',                  'table')

    ),
    resolved AS (
        SELECT
            c.tbl_schema,
            c.tbl_name,
            c.entity_short,
            c.entity_class,
            c.gov_level,
            c.sec_tier,
            c.mutab,
            c.label_s,
            c.label_p,
            c.backing,
            replace(lower(c.tbl_name), '_', '-') AS computed_slug,
            c.tbl_name                           AS computed_code,
            CASE c.tbl_schema
                WHEN 'shared'   THEN v_fnd
                WHEN 'control'  THEN v_fnd
                ELSE                 v_acc
            END AS mod_id
        FROM corrections c
        -- Only include rows where the table or view actually exists in the DB
        WHERE EXISTS (
            SELECT 1 FROM information_schema.tables  t
             WHERE t.table_schema = c.tbl_schema AND t.table_name = c.tbl_name
               AND t.table_type IN ('BASE TABLE', 'VIEW')
        )
    )
    INSERT INTO control.entity (
        module_id, name, entity_short, entity_code, slug,
        entity_class, ownership_model, kind, backing_type,
        governance_level, security_tier, mutability, mapping_mode,
        table_schema, table_name, label_singular, label_plural,
        status, created_by, updated_by
    )
    SELECT
        r.mod_id,
        r.computed_code,      -- name (table-name-only)
        r.entity_short,
        r.computed_code,      -- entity_code (table-name-only)
        r.computed_slug,
        r.entity_class,
        'system', 'ent',
        r.backing,
        r.gov_level,
        r.sec_tier,
        r.mutab,
        'exclusive',
        r.tbl_schema, r.tbl_name,
        r.label_s, r.label_p,
        'ACTIVE', v_su, v_su
    FROM resolved r
    ON CONFLICT (table_schema, table_name) DO UPDATE SET
        -- Safe fields only (Phase 1a).
        -- entity_code and name are NOT updated here to avoid breaking
        -- entity_lifecycle / entity_operation text references and TS code.
        slug             = EXCLUDED.slug,
        entity_short     = EXCLUDED.entity_short,
        entity_class     = EXCLUDED.entity_class,
        governance_level = EXCLUDED.governance_level,
        security_tier    = EXCLUDED.security_tier,
        mutability       = EXCLUDED.mutability,
        mapping_mode     = EXCLUDED.mapping_mode,
        label_singular   = EXCLUDED.label_singular,
        label_plural     = EXCLUDED.label_plural,
        backing_type     = EXCLUDED.backing_type,
        updated_at       = now(),
        updated_by       = v_su
    WHERE control.entity.tenant_id IS NULL
      AND control.entity.table_schema IN ('control', 'document', 'master', 'shared');

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RAISE NOTICE 'Phase 1a entity correction: % rows upserted (inserted + updated)', v_count;

    -- ── entity_version seed for newly-inserted entities lacking version 1 ─────
    INSERT INTO control.entity_version (
        entity_id, tenant_id, version_no, status, label,
        change_type, effective_from, created_by, updated_by
    )
    SELECT
        e.id, e.tenant_id, 1, 'EFFECTIVE',
        'Initial Version',
        'structural', now(), v_su, v_su
    FROM control.entity e
    WHERE e.tenant_id IS NULL
      AND e.table_schema IN ('control', 'document', 'master', 'shared')
      AND NOT EXISTS (
          SELECT 1 FROM control.entity_version ev
           WHERE ev.entity_id = e.id AND ev.version_no = 1
      );

    RAISE NOTICE 'Phase 1a complete.';
END $$;
